sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float scale;
uniform float evolution;
uniform float shift;
uniform float saturation;
uniform float alpha;
uniform float blend;
uniform float seed;
float hash13(float3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}
float vnoise(float3 p) {
    float3 i = floor(p);
    float3 f = fract(p);
    f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    float a = mix(hash13(i), hash13(i + float3(1, 0, 0)), f.x);
    float b = mix(hash13(i + float3(0, 1, 0)), hash13(i + float3(1, 1, 0)), f.x);
    float c = mix(hash13(i + float3(0, 0, 1)), hash13(i + float3(1, 0, 1)), f.x);
    float d = mix(hash13(i + float3(0, 1, 1)), hash13(i + float3(1, 1, 1)), f.x);
    return mix(mix(a, b, f.y), mix(c, d, f.y), f.z);
}
float fbm(float3 p, float octaves, float2 drift, float gain) {
    float sum = 0.0;
    float amp = 0.5;
    float norm = 0.0;
    for (int i = 0; i < 9; i++) {
        if (float(i) >= octaves) break;
        sum += amp * vnoise(p);
        norm += amp;
        amp *= gain;
        p = float3(p.xy * 2.03 + drift + float2(17.13, 9.71), p.z * 1.7 + 3.1);
    }
    return sum / max(norm, 0.0001);
}
float3 hue2rgb(float h) {
    return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
}
float3 blendWith(float m, float3 b, float3 s) {
    if (m < 0.5) return s;
    if (m < 1.5) return b * s;
    if (m < 2.5) return b + s - b * s;
    if (m < 3.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(0.5, b));
    if (m < 4.5) {
        float3 d = mix(sqrt(b), ((16.0 * b - 12.0) * b + 4.0) * b, step(b, float3(0.25)));
        return mix(b - (1.0 - 2.0 * s) * b * (1.0 - b), b + (2.0 * s - 1.0) * (d - b), step(0.5, s));
    }
    if (m < 5.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(0.5, s));
    if (m < 6.5) return min(b + s, 1.0);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return max(b, s);
    if (m < 9.5) return abs(b - s);
    if (m < 10.5) return min(b / max(1.0 - s, 0.0001), 1.0);
    return 1.0 - min((1.0 - b) / max(s, 0.0001), 1.0);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float unit = 0.4 * size.y * max(scale, 0.01);
    float2 p = (coord - size * 0.5) / unit + seed * float2(11.3, 5.9);
    float w = fbm(float3(p, evolution), 5.0, float2(0.0), 0.5);
    float v = fbm(float3(p + 3.0 * w + float2(2.7, 8.1), evolution * 0.7), 5.0, float2(0.0), 0.5);
    float3 film = mix(float3(1.0), hue2rgb(fract(v * 2.5 + shift)), clamp(saturation, 0.0, 1.0));
    float3 base = float3(src.rgb) / float(src.a);
    float3 rgb = mix(base, clamp(blendWith(blend, base, film), 0.0, 1.0), clamp(alpha, 0.0, 1.0));
    return half4(half3(rgb) * src.a, src.a);
}
